6	 * Derives an owner's locality (its canonical region). The postcode is preferred: the region whose
7	 * postcode range contains it (see {@link RegionPostcodes#regionOf(int)}) wins, which disambiguates
8	 * cities that share a name. Only when the postcode is absent, malformed or in no known range does it
9	 * fall back to the city-to-region table (see {@link CityRegion#of(String)}). Known cities therefore
10	 * resolve to the same region as before.
11	 */
12	public final class Locality {
13	
14	    private static final Pattern FOUR_DIGITS = Pattern.compile("\\d{4}");
15	
16	    private Locality() {
17	    }
18	
19	    /**
20	     * The canonical region for {@code city} and {@code postcode}, preferring the postcode and falling
21	     * back to the city. Never {@code null}: an unresolved city yields {@link CityRegion#UNKNOWN}.
22	     */
23	    public static String of(String city, String postcode) {
24	        String fromPostcode = regionOfPostcode(postcode);
25	        return fromPostcode != null ? fromPostcode : CityRegion.of(city);
26	    }
27	
28	    /** The region for a well-formed 4-digit postcode in a known range, else {@code null}. */
29	    private static String regionOfPostcode(String postcode) {
30	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
31	            return null;
32	        }
33	        return RegionPostcodes.regionOf(Integer.parseInt(postcode));
34	    }
35	}
