1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Bands {@link MembershipPoints membership points} into a membership level, a number from 1 to 4:
5	 * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more points. Because a newly created
6	 * owner has zero tenure, a new owner never earns the tenure points and so never exceeds level 3.
7	 */
